/**
 * Apuntes BootDev — read-only viewer.
 * Loads data/index.json (generated by build_index.py) and renders the course
 * tree, chapter views, quick search and the key concepts panel.
 */

const INDEX_URL = "data/index.json";
const SUPPORTED_SCHEMA_VERSION = 1;
const THEME_STORAGE_KEY = "bootdev-viewer-theme";
const SEARCH_DEBOUNCE_MS = 120;
const MAX_SEARCH_RESULTS = 60;
const SNIPPET_RADIUS = 70;
const MOBILE_QUERY = "(max-width: 768px)";
const COPY_FEEDBACK_MS = 1800;

const PYTHON_KEYWORDS = new Set([
  "and", "as", "assert", "async", "await", "break", "class", "continue", "def", "del",
  "elif", "else", "except", "finally", "for", "from", "global", "if", "import", "in",
  "is", "lambda", "match", "case", "nonlocal", "not", "or", "pass", "raise", "return",
  "try", "while", "with", "yield",
]);
const PYTHON_CONSTANTS = new Set(["True", "False", "None"]);
const PYTHON_BUILTINS = new Set([
  "abs", "all", "any", "bool", "dict", "enumerate", "filter", "float", "input", "int",
  "isinstance", "len", "list", "map", "max", "min", "open", "print", "range", "round",
  "set", "sorted", "str", "sum", "tuple", "type", "zip",
]);

const PYTHON_TOKEN_PATTERN = new RegExp(
  [
    String.raw`(?<comment>#[^\n]*)`,
    String.raw`(?<string>[rRbBuUfF]{0,2}(?:"""[\s\S]*?(?:"""|$)|'''[\s\S]*?(?:'''|$)|"(?:\\.|[^"\\\n])*"?|'(?:\\.|[^'\\\n])*'?))`,
    String.raw`(?<number>\b\d+(?:\.\d+)?(?:[eE][-+]?\d+)?\b)`,
    String.raw`(?<name>[A-Za-z_]\w*)`,
    String.raw`(?<newline>\n)`,
    String.raw`(?<other>[^\S\n]+|.)`,
  ].join("|"),
  "gy",
);

const dateFormatter = new Intl.DateTimeFormat("es-ES", { dateStyle: "long", timeStyle: "short" });

const state = {
  index: null,
  files: [],
  fileByKey: new Map(),
  glossaryById: new Map(),
  searchEntries: [],
  currentFileKey: null,
  activeExerciseIndex: null,
  collapsedCourses: new Set(),
  query: "",
  conceptId: null,
  exerciseObserver: null,
  toastTimer: null,
};

const elements = {};

/* -------------------------------------------------------------------------- */
/* Generic helpers                                                            */
/* -------------------------------------------------------------------------- */

function escapeHtml(text) {
  const replacements = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
  return String(text).replace(/[&<>"']/g, (character) => replacements[character]);
}

function normalizeText(text) {
  return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
}

function createElement(tag, options = {}, children = []) {
  const element = document.createElement(tag);
  if (options.className) element.className = options.className;
  if (options.text !== undefined) element.textContent = options.text;
  if (options.html !== undefined) element.innerHTML = options.html;
  for (const [name, value] of Object.entries(options.attrs ?? {})) {
    if (value !== null && value !== undefined && value !== false) element.setAttribute(name, value);
  }
  for (const child of children) {
    if (child) element.append(child);
  }
  return element;
}

function padNumber(number) {
  return String(number).padStart(2, "0");
}

function formatDate(isoDate) {
  const date = new Date(isoDate);
  return Number.isNaN(date.getTime()) ? isoDate : dateFormatter.format(date);
}

function pluralize(count, singular, plural) {
  return `${count} ${count === 1 ? singular : plural}`;
}

function debounce(callback, delay) {
  let timer = null;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => callback(...args), delay);
  };
}

function showToast(message) {
  elements.toast.textContent = message;
  elements.toast.hidden = false;
  clearTimeout(state.toastTimer);
  state.toastTimer = setTimeout(() => {
    elements.toast.hidden = true;
  }, 4000);
}

function describeFile(file) {
  return file.kind === "chapter" ? `Capítulo ${padNumber(file.number)}` : "Extra";
}

/* -------------------------------------------------------------------------- */
/* Data loading                                                               */
/* -------------------------------------------------------------------------- */

async function loadIndex() {
  const response = await fetch(INDEX_URL, { cache: "no-store" });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return response.json();
}

function prepareIndex(index) {
  state.index = index;
  for (const entry of index.glossary ?? []) state.glossaryById.set(entry.id, entry);

  for (const course of index.courses ?? []) {
    for (const file of [...course.chapters, ...course.extras]) {
      file.course = course;
      file.key = `${course.id}/${file.id}`;
      state.files.push(file);
      state.fileByKey.set(file.key, file);
    }
  }
  state.searchEntries = buildSearchEntries(state.files);
}

function buildSearchEntries(files) {
  return files.flatMap((file) =>
    file.exercises.map((exercise) => {
      const theory = exercise.segments.filter((s) => s.type === "theory").map((s) => s.text);
      const code = exercise.segments.filter((s) => s.type === "code").map((s) => s.text);
      const conceptTerms = exercise.concepts.map((id) => state.glossaryById.get(id)?.term ?? id);
      const snippetSource = [...theory, ...code].join("  ").replace(/\s+/g, " ");
      return {
        file,
        exercise,
        normalizedTitle: normalizeText(exercise.title),
        haystack: normalizeText([exercise.title, ...theory, ...code, ...conceptTerms].join("\n")),
        snippetSource,
      };
    }),
  );
}

/* -------------------------------------------------------------------------- */
/* Routing                                                                    */
/* -------------------------------------------------------------------------- */

function buildHash(file, exerciseIndex = null) {
  const parts = ["#", encodeURIComponent(file.course.id), encodeURIComponent(file.id)];
  if (exerciseIndex) parts.push(String(exerciseIndex));
  return parts.join("/");
}

function parseHash(hash) {
  const parts = hash.replace(/^#\/?/, "").split("/").filter(Boolean).map(decodeURIComponent);
  if (parts.length < 2) return { view: "home" };
  const exerciseIndex = parts[2] ? Number.parseInt(parts[2], 10) : null;
  return { view: "file", key: `${parts[0]}/${parts[1]}`, exerciseIndex };
}

function handleRoute({ isInitial = false } = {}) {
  const route = parseHash(window.location.hash);
  const file = route.view === "file" ? state.fileByKey.get(route.key) : null;

  if (route.view === "file" && !file) {
    showToast("Ese capítulo no existe en el índice. Se muestra la portada.");
  }

  if (file) {
    const isSameFile = state.currentFileKey === file.key;
    if (!isSameFile) renderFileView(file);
    scrollToRouteTarget(file, route.exerciseIndex, isSameFile);
  } else {
    renderHomeView();
    window.scrollTo(0, 0);
  }

  renderTree();
  renderConceptsPanel();
  updateMobileTitle();
  closeMenu();
  if (!isInitial) elements.main.focus({ preventScroll: true });
}

function scrollToRouteTarget(file, exerciseIndex, isSameFile) {
  if (!exerciseIndex) {
    if (!isSameFile) window.scrollTo(0, 0);
    return;
  }
  const target = document.getElementById(`exercise-${exerciseIndex}`);
  if (!target) {
    showToast(`${describeFile(file)} no tiene el ejercicio ${exerciseIndex}.`);
    return;
  }
  setActiveExercise(exerciseIndex);
  requestAnimationFrame(() => target.scrollIntoView({ block: "start" }));
}

/* -------------------------------------------------------------------------- */
/* Sidebar: course tree                                                       */
/* -------------------------------------------------------------------------- */

function renderTree() {
  const fragment = document.createDocumentFragment();
  for (const course of state.index.courses) {
    fragment.append(renderTreeCourse(course));
  }
  elements.tree.replaceChildren(fragment);
}

function renderTreeCourse(course) {
  const details = createElement("details", {
    className: "tree-course",
    attrs: { open: !state.collapsedCourses.has(course.id) },
  });
  details.append(createElement("summary", { text: course.title }));
  details.addEventListener("toggle", () => {
    if (details.open) state.collapsedCourses.delete(course.id);
    else state.collapsedCourses.add(course.id);
  });

  if (course.chapters.length) {
    details.append(
      createElement("p", { className: "tree-group-label", text: "Capítulos" }),
      renderTreeFileList(course.chapters),
    );
  }
  if (course.extras.length) {
    details.append(
      createElement("p", { className: "tree-group-label", text: "Extras" }),
      renderTreeFileList(course.extras),
    );
  }
  return details;
}

function renderTreeFileList(files) {
  const list = createElement("ul");
  for (const file of files) list.append(renderTreeFile(file));
  return list;
}

function renderTreeFile(file) {
  const isCurrent = file.key === state.currentFileKey;
  const link = createElement(
    "a",
    { attrs: { href: buildHash(file), "aria-current": isCurrent ? "page" : null } },
    [
      createElement("span", {
        className: "tree-file-number",
        text: file.kind === "chapter" ? padNumber(file.number) : "+",
        attrs: { "aria-hidden": "true" },
      }),
      createElement("span", { text: file.title }),
    ],
  );
  const item = createElement("li", { className: "tree-file" }, [link]);
  if (isCurrent && file.exercises.length) item.append(renderTreeExercises(file));
  return item;
}

function renderTreeExercises(file) {
  const list = createElement("ul", { className: "tree-exercises", attrs: { "aria-label": "Ejercicios" } });
  for (const exercise of file.exercises) {
    const isActive = exercise.index === state.activeExerciseIndex;
    list.append(
      createElement("li", {}, [
        createElement("a", {
          text: exercise.title,
          attrs: {
            href: buildHash(file, exercise.index),
            "data-exercise-index": exercise.index,
            "aria-current": isActive ? "location" : null,
          },
        }),
      ]),
    );
  }
  return list;
}

function setActiveExercise(exerciseIndex) {
  state.activeExerciseIndex = exerciseIndex;
  for (const link of elements.tree.querySelectorAll("[data-exercise-index]")) {
    const isActive = Number(link.dataset.exerciseIndex) === exerciseIndex;
    if (isActive) link.setAttribute("aria-current", "location");
    else link.removeAttribute("aria-current");
  }
}

function observeExercises() {
  state.exerciseObserver?.disconnect();
  state.exerciseObserver = new IntersectionObserver(
    (entries) => {
      const visible = entries.filter((entry) => entry.isIntersecting);
      if (visible.length) setActiveExercise(Number(visible[0].target.dataset.exerciseIndex));
    },
    { rootMargin: "-15% 0px -75% 0px" },
  );
  for (const section of elements.view.querySelectorAll(".exercise")) {
    state.exerciseObserver.observe(section);
  }
}

/* -------------------------------------------------------------------------- */
/* Main view: chapter                                                         */
/* -------------------------------------------------------------------------- */

function renderFileView(file) {
  state.currentFileKey = file.key;
  state.activeExerciseIndex = file.exercises[0]?.index ?? null;

  const children = [renderChapterHeader(file)];
  if (file.error) {
    children.push(renderNotice("No se pudo mostrar este fichero", file.error));
  } else if (!file.exercises.length) {
    children.push(renderNotice("Este fichero está vacío", "No contiene teoría ni código para mostrar."));
  } else {
    for (const exercise of file.exercises) children.push(renderExercise(exercise));
  }

  elements.view.replaceChildren(...children);
  document.title = `${file.title} | Apuntes BootDev`;
  observeExercises();
}

function renderChapterHeader(file) {
  const titleChildren = [];
  if (file.kind === "chapter") {
    titleChildren.push(createElement("span", { className: "chapter-number", text: padNumber(file.number) }));
  }
  titleChildren.push(createElement("span", { text: file.title }));

  const meta = createElement("dl", { className: "chapter-meta" }, [
    renderMetaItem("Tipo", file.kind === "chapter" ? "Capítulo" : "Extra"),
    renderMetaItem("Ejercicios", String(file.exerciseCount)),
    renderMetaItem("Líneas", String(file.lineCount)),
    renderMetaItem("Modificado", formatDate(file.modifiedAt)),
  ]);

  const header = createElement("header", { className: "chapter-head" }, [
    createElement("div", { className: "chapter-tags" }, [
      renderBadge("BootDev", "badge-source"),
      renderBadge("Python", "badge-language"),
      createElement("span", { className: "chapter-path", text: file.path }),
    ]),
    createElement("h1", { className: "chapter-title" }, titleChildren),
    meta,
  ]);

  if (file.warnings?.length) {
    header.append(
      createElement("div", { className: "notice chapter-warnings", attrs: { role: "note" } }, [
        createElement("p", { text: file.warnings.join(" ") }),
      ]),
    );
  }
  return header;
}

function renderMetaItem(label, value) {
  return createElement("div", {}, [createElement("dt", { text: label }), createElement("dd", { text: value })]);
}

function renderExercise(exercise) {
  const headingId = `exercise-${exercise.index}-title`;
  const section = createElement("section", {
    className: "exercise",
    attrs: { id: `exercise-${exercise.index}`, "aria-labelledby": headingId, "data-exercise-index": exercise.index },
  });

  const title = createElement(
    "h2",
    { className: `exercise-title${exercise.hasOwnTitle ? "" : " is-untitled"}`, attrs: { id: headingId } },
    [
      createElement("span", { className: "exercise-number", text: padNumber(exercise.index) }),
      createElement("span", { text: exercise.title }),
    ],
  );
  const lines = createElement("span", {
    className: "exercise-lines",
    text: `líneas ${exercise.startLine}–${exercise.endLine}`,
  });

  section.append(createElement("div", { className: "exercise-head" }, [title, lines]));
  if (exercise.concepts.length) section.append(renderConceptChips(exercise.concepts));
  for (const step of groupSegmentsIntoSteps(exercise.segments)) section.append(renderStep(step));
  return section;
}

function renderConceptChips(conceptIds) {
  const list = createElement("ul", { className: "concept-chips", attrs: { "aria-label": "Conceptos del ejercicio" } });
  for (const conceptId of conceptIds) {
    const entry = state.glossaryById.get(conceptId);
    if (!entry) continue;
    list.append(
      createElement("li", {}, [
        createElement("button", {
          className: "concept-chip",
          text: entry.term,
          attrs: {
            type: "button",
            title: entry.definition,
            "data-concept-id": conceptId,
            "aria-pressed": String(state.conceptId === conceptId),
          },
        }),
      ]),
    );
  }
  return list;
}

/** Pairs each theory segment with the code segment that follows it. */
function groupSegmentsIntoSteps(segments) {
  const steps = [];
  let current = null;
  for (const segment of segments) {
    if (segment.type === "theory") {
      current = { theory: segment, code: null };
      steps.push(current);
    } else if (current && !current.code) {
      current.code = segment;
    } else {
      current = { theory: null, code: segment };
      steps.push(current);
    }
  }
  return steps;
}

function renderStep(step) {
  const classes = ["step"];
  if (step.theory) classes.push("has-notes");
  if (step.theory && !step.code) classes.push("is-theory-only");

  const notes = createElement("div", { className: "step-notes", text: step.theory?.text ?? "" });
  const container = createElement("div", { className: classes.join(" ") }, [notes]);
  if (step.code) container.append(renderCodePanel(step.code));
  return container;
}

/** Normalizes line endings and drops trailing blank lines so display and copy match. */
function cleanCodeText(text) {
  return text.replace(/\r\n?/g, "\n").replace(/\s+$/, "");
}

function renderCodePanel(segment) {
  const cleanText = cleanCodeText(segment.text);
  const lineCount = cleanText.split("\n").length;
  const endLine = segment.startLine + lineCount - 1;
  const copyButton = createElement("button", {
    className: "copy-button",
    text: "Copiar",
    attrs: { type: "button", "aria-label": `Copiar código, líneas ${segment.startLine} a ${endLine}` },
  });
  copyButton.addEventListener("click", () => copyCode(cleanText, copyButton));

  const toolbar = createElement("div", { className: "code-toolbar" }, [
    createElement("span", { className: "badge badge-language", text: "Python" }),
    createElement("span", { className: "code-range", text: `Líneas ${segment.startLine}–${endLine}` }),
    copyButton,
  ]);
  return createElement("div", { className: "step-code" }, [toolbar, renderCodeBlock(segment, cleanText)]);
}

async function writeToClipboard(text) {
  if (navigator.clipboard?.writeText && window.isSecureContext) {
    await navigator.clipboard.writeText(text);
    return;
  }
  const helper = createElement("textarea", { attrs: { readonly: "", "aria-hidden": "true" } });
  helper.value = text;
  helper.className = "clipboard-helper";
  document.body.append(helper);
  helper.select();
  const isCopied = document.execCommand("copy");
  helper.remove();
  if (!isCopied) throw new Error("copy failed");
}

async function copyCode(text, button) {
  try {
    await writeToClipboard(text);
    button.textContent = "Copiado";
    button.dataset.state = "done";
  } catch {
    button.textContent = "No se pudo copiar";
    button.dataset.state = "error";
  }
  setTimeout(() => {
    button.textContent = "Copiar";
    delete button.dataset.state;
  }, COPY_FEEDBACK_MS);
}

function renderCodeBlock(segment, cleanText) {
  const boilerplateLines = new Set(segment.boilerplateLines ?? []);
  const linesHtml = highlightPythonLines(cleanText).map((lineHtml, offset) => {
    const lineNumber = segment.startLine + offset;
    const extraClass = boilerplateLines.has(lineNumber) ? " is-boilerplate" : "";
    return (
      `<span class="code-line${extraClass}">` +
      `<span class="code-line-number" aria-hidden="true">${lineNumber}</span>` +
      `<span class="code-line-content">${lineHtml || " "}</span></span>`
    );
  });

  const code = createElement("code", { html: linesHtml.join("") });
  return createElement(
    "pre",
    {
      className: "code-block",
      attrs: { tabindex: "0", "aria-label": `Código Python, líneas ${segment.startLine} a ${segment.startLine + linesHtml.length - 1}` },
    },
    [code],
  );
}

function renderNotice(title, message, commands = null) {
  const notice = createElement("div", { className: "notice", attrs: { role: "note" } }, [
    createElement("h1", { text: title }),
    createElement("p", { text: message }),
  ]);
  if (commands) notice.append(createElement("pre", {}, [createElement("code", { text: commands })]));
  return notice;
}

/* -------------------------------------------------------------------------- */
/* Python syntax highlighting (read-only, no dependencies)                    */
/* -------------------------------------------------------------------------- */

/** Returns one escaped HTML string per source line. */
function highlightPythonLines(source) {
  const lines = [""];
  let previousName = "";
  PYTHON_TOKEN_PATTERN.lastIndex = 0;

  for (const match of source.matchAll(PYTHON_TOKEN_PATTERN)) {
    const { comment, string, number, name, newline } = match.groups;
    if (newline !== undefined) {
      lines.push("");
    } else if (comment !== undefined) {
      appendToken(lines, comment, "tok-comment");
    } else if (string !== undefined) {
      for (const piece of splitStringToken(string)) appendToken(lines, piece.text, piece.className);
    } else if (number !== undefined) {
      appendToken(lines, number, "tok-number");
    } else if (name !== undefined) {
      const isCall = source[match.index + name.length] === "(";
      appendToken(lines, name, classifyName(name, previousName, isCall));
      previousName = name;
    } else {
      appendToken(lines, match[0], null);
    }
  }
  return lines;
}

function classifyName(name, previousName, isCall) {
  if (PYTHON_CONSTANTS.has(name)) return "tok-constant";
  if (PYTHON_KEYWORDS.has(name)) return "tok-keyword";
  if (PYTHON_BUILTINS.has(name)) return "tok-builtin";
  if (previousName === "def" || isCall) return "tok-function";
  return null;
}

/** Splits f-strings so that {expressions} get their own colour. */
function splitStringToken(text) {
  const prefix = text.match(/^[rRbBuUfF]*/)[0];
  if (!/[fF]/.test(prefix)) return [{ text, className: "tok-string" }];

  const pieces = [];
  let lastIndex = 0;
  for (const match of text.matchAll(/\{[^{}\n]*\}/g)) {
    if (match.index > lastIndex) pieces.push({ text: text.slice(lastIndex, match.index), className: "tok-string" });
    pieces.push({ text: match[0], className: "tok-interp" });
    lastIndex = match.index + match[0].length;
  }
  if (lastIndex < text.length) pieces.push({ text: text.slice(lastIndex), className: "tok-string" });
  return pieces;
}

function appendToken(lines, text, className) {
  text.split("\n").forEach((part, position) => {
    if (position > 0) lines.push("");
    if (!part) return;
    const escaped = escapeHtml(part);
    lines[lines.length - 1] += className ? `<span class="${className}">${escaped}</span>` : escaped;
  });
}

/* -------------------------------------------------------------------------- */
/* Main view: home                                                            */
/* -------------------------------------------------------------------------- */

function renderHomeView() {
  state.currentFileKey = null;
  state.activeExerciseIndex = null;
  state.exerciseObserver?.disconnect();
  document.title = "Apuntes BootDev";

  const children = [
    createElement("section", { className: "home-intro" }, [
      createElement("h1", { className: "home-title", text: "Apuntes BootDev" }),
      createElement("p", {
        className: "home-lead",
        text: "La teoría y el código resuelto de cada capítulo, lado a lado, para repasar de un vistazo.",
      }),
    ]),
  ];

  for (const course of state.index.courses) children.push(renderCourseToc(course));

  if (state.index.home?.markdown) {
    children.push(
      createElement("section", { className: "readme", attrs: { "aria-label": "README del repositorio" } }, [
        createElement("p", { className: "readme-label", text: state.index.home.path }),
        createElement("div", { html: renderMarkdown(state.index.home.markdown) }),
      ]),
    );
  }

  elements.view.replaceChildren(...children);
}

function renderCourseToc(course) {
  const section = createElement("section", { className: "course-toc" }, [
    createElement("h2", { text: course.title }),
  ]);
  const list = createElement("ol", { className: "toc-list" });
  for (const file of [...course.chapters, ...course.extras]) list.append(renderTocItem(file));
  section.append(list);
  return section;
}

function renderTocItem(file) {
  const titledExercises = file.exercises.filter((exercise) => exercise.hasOwnTitle).map((e) => e.title);
  const detail = titledExercises.length ? titledExercises.join(", ") : "Sin títulos de ejercicio";
  return createElement("li", {}, [
    createElement("a", { attrs: { href: buildHash(file) } }, [
      createElement("span", {
        className: "toc-number",
        text: file.kind === "chapter" ? padNumber(file.number) : "+",
        attrs: { "aria-hidden": "true" },
      }),
      createElement("span", { className: "toc-title", text: file.title }, [
        createElement("span", { className: "toc-detail", text: detail }),
      ]),
      createElement("span", {
        className: "toc-count",
        text: pluralize(file.exerciseCount, "ejercicio", "ejercicios"),
      }),
    ]),
  ]);
}

/* -------------------------------------------------------------------------- */
/* Minimal Markdown renderer (escapes everything, skips raw HTML)             */
/* -------------------------------------------------------------------------- */

const MARKDOWN_BLOCK_START = /^(\s*$|\s*<|```|#{1,6}\s|>|\s*[-*+]\s|\s*\d+\.\s|(-{3,}|\*{3,}|_{3,})\s*$)/;

function renderMarkdown(markdown) {
  const lines = markdown.replace(/\r\n?/g, "\n").split("\n");
  const html = [];
  let position = 0;

  while (position < lines.length) {
    const line = lines[position];
    if (/^\s*$/.test(line) || /^\s*</.test(line)) {
      position += 1;
    } else if (line.startsWith("```")) {
      position = renderMarkdownFence(lines, position, html);
    } else if (/^#{1,6}\s/.test(line)) {
      const [, hashes, text] = line.match(/^(#{1,6})\s+(.*)$/);
      const level = Math.min(hashes.length + 1, 6);
      html.push(`<h${level}>${renderInlineMarkdown(text)}</h${level}>`);
      position += 1;
    } else if (/^(-{3,}|\*{3,}|_{3,})\s*$/.test(line)) {
      html.push("<hr>");
      position += 1;
    } else if (line.includes("|") && /^\s*\|?\s*:?-{3,}/.test(lines[position + 1] ?? "")) {
      position = renderMarkdownTable(lines, position, html);
    } else if (/^>/.test(line)) {
      position = renderMarkdownCollected(lines, position, html, /^>\s?/, "blockquote");
    } else if (/^\s*[-*+]\s/.test(line)) {
      position = renderMarkdownList(lines, position, html, /^\s*[-*+]\s+/, "ul");
    } else if (/^\s*\d+\.\s/.test(line)) {
      position = renderMarkdownList(lines, position, html, /^\s*\d+\.\s+/, "ol");
    } else {
      position = renderMarkdownParagraph(lines, position, html);
    }
  }
  return html.join("\n");
}

function renderMarkdownFence(lines, start, html) {
  const body = [];
  let position = start + 1;
  while (position < lines.length && !lines[position].startsWith("```")) {
    body.push(lines[position]);
    position += 1;
  }
  html.push(`<pre><code>${escapeHtml(body.join("\n"))}</code></pre>`);
  return position + 1;
}

function splitTableRow(line) {
  return line.trim().replace(/^\|/, "").replace(/\|$/, "").split("|").map((cell) => cell.trim());
}

function renderMarkdownTable(lines, start, html) {
  const headers = splitTableRow(lines[start]);
  let position = start + 2;
  const rows = [];
  while (position < lines.length && lines[position].includes("|") && lines[position].trim()) {
    rows.push(splitTableRow(lines[position]));
    position += 1;
  }
  const head = headers.map((cell) => `<th scope="col">${renderInlineMarkdown(cell)}</th>`).join("");
  const body = rows
    .map((row) => `<tr>${row.map((cell) => `<td>${renderInlineMarkdown(cell)}</td>`).join("")}</tr>`)
    .join("");
  html.push(`<div class="readme-table-wrap"><table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`);
  return position;
}

function renderMarkdownCollected(lines, start, html, marker, tag) {
  const body = [];
  let position = start;
  while (position < lines.length && marker.test(lines[position])) {
    body.push(lines[position].replace(marker, ""));
    position += 1;
  }
  html.push(`<${tag}><p>${renderInlineMarkdown(body.join(" "))}</p></${tag}>`);
  return position;
}

function renderMarkdownList(lines, start, html, marker, tag) {
  const items = [];
  let position = start;
  while (position < lines.length && marker.test(lines[position])) {
    items.push(`<li>${renderInlineMarkdown(lines[position].replace(marker, ""))}</li>`);
    position += 1;
  }
  html.push(`<${tag}>${items.join("")}</${tag}>`);
  return position;
}

function renderMarkdownParagraph(lines, start, html) {
  const body = [lines[start]];
  let position = start + 1;
  while (position < lines.length && !MARKDOWN_BLOCK_START.test(lines[position])) {
    body.push(lines[position]);
    position += 1;
  }
  html.push(`<p>${renderInlineMarkdown(body.join(" "))}</p>`);
  return position;
}

function isSafeUrl(url) {
  return /^(https?:|mailto:|#)/i.test(url);
}

function renderInlineMarkdown(text) {
  const codeSpans = [];
  let html = escapeHtml(text).replace(/`([^`]+)`/g, (_, code) => {
    codeSpans.push(code);
    return `\u0000${codeSpans.length - 1}\u0000`;
  });

  // Images are shown as their alt text so the viewer works fully offline.
  html = html.replace(/!\[([^\]]*)\]\(([^)\s]+)[^)]*\)/g, (_, alt) => alt);
  html = html.replace(/\[([^\]]+)\]\(([^)\s]+)[^)]*\)/g, (_, label, url) =>
    isSafeUrl(url) ? `<a href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>` : label,
  );
  html = html.replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
  html = html.replace(/(^|[^*\w])\*([^*\n]+)\*(?!\w)/g, "$1<em>$2</em>");

  return html.replace(/\u0000(\d+)\u0000/g, (_, index) => `<code>${codeSpans[Number(index)]}</code>`);
}

/* -------------------------------------------------------------------------- */
/* Concepts panel                                                             */
/* -------------------------------------------------------------------------- */

function countConcepts(files) {
  const counts = new Map();
  for (const file of files) {
    for (const exercise of file.exercises) {
      for (const conceptId of exercise.concepts) counts.set(conceptId, (counts.get(conceptId) ?? 0) + 1);
    }
  }
  return counts;
}

function renderConceptsPanel() {
  const currentFile = state.fileByKey.get(state.currentFileKey);
  const counts = countConcepts(currentFile ? [currentFile] : state.files);
  const glossaryOrder = [...state.glossaryById.keys()];
  const conceptIds = [...counts.keys()]
    .filter((id) => state.glossaryById.has(id))
    .sort((a, b) => counts.get(b) - counts.get(a) || glossaryOrder.indexOf(a) - glossaryOrder.indexOf(b));

  elements.conceptsHint.textContent = conceptIds.length
    ? currentFile
      ? "Detectados en este capítulo. Pulsa uno para ver en qué ejercicios aparece."
      : "Detectados en todo el curso. Pulsa uno para ver en qué ejercicios aparece."
    : "No se han detectado conceptos del glosario en este fichero.";

  const items = conceptIds.map((conceptId) => renderConceptItem(state.glossaryById.get(conceptId), counts.get(conceptId)));
  elements.chapterConcepts.replaceChildren(...items);
}

function renderBadge(text, variant = "") {
  return createElement("span", { className: `badge ${variant}`.trim(), text });
}

function renderConceptItem(entry, count) {
  const button = createElement(
    "button",
    {
      className: "concept-button",
      attrs: {
        type: "button",
        "data-concept-id": entry.id,
        "aria-pressed": String(state.conceptId === entry.id),
        "aria-label": `${entry.term}, ${pluralize(count, "ejercicio", "ejercicios")}`,
      },
    },
    [
      createElement("span", { className: "concept-term", text: entry.term }),
      createElement("span", { className: "concept-count", text: String(count), attrs: { "aria-hidden": "true" } }),
    ],
  );
  const meta = createElement("div", { className: "concept-meta" }, [
    renderBadge(entry.category ?? "Otros", "badge-category"),
  ]);
  return createElement("li", { className: "concept-item" }, [
    button,
    meta,
    createElement("p", { className: "concept-definition", text: entry.definition }),
  ]);
}

function renderGlossary() {
  const groups = new Map();
  for (const entry of state.glossaryById.values()) {
    const category = entry.category ?? "Otros";
    if (!groups.has(category)) groups.set(category, []);
    groups.get(category).push(entry);
  }

  const fragment = document.createDocumentFragment();
  for (const [category, entries] of groups) {
    const list = createElement("dl");
    for (const entry of entries) {
      list.append(createElement("dt", { text: entry.term }), createElement("dd", { text: entry.definition }));
    }
    fragment.append(
      createElement("details", { className: "glossary-group" }, [
        createElement("summary", { text: `${category} (${entries.length})` }),
        list,
      ]),
    );
  }
  if (!groups.size) fragment.append(createElement("p", { className: "panel-hint", text: "El glosario está vacío." }));
  elements.glossary.replaceChildren(fragment);
}

function syncConceptButtons() {
  for (const button of document.querySelectorAll("[data-concept-id]")) {
    button.setAttribute("aria-pressed", String(button.dataset.conceptId === state.conceptId));
  }
}

function toggleConceptFilter(conceptId) {
  state.conceptId = state.conceptId === conceptId ? null : conceptId;
  syncConceptButtons();
  runSearch();
  if (state.conceptId && window.matchMedia(MOBILE_QUERY).matches) openMenu();
}

/* -------------------------------------------------------------------------- */
/* Search                                                                     */
/* -------------------------------------------------------------------------- */

function getSearchTerms() {
  return normalizeText(state.query).split(/\s+/).filter(Boolean);
}

function findMatches(terms) {
  return state.searchEntries
    .filter((entry) => !state.conceptId || entry.exercise.concepts.includes(state.conceptId))
    .filter((entry) => terms.every((term) => entry.haystack.includes(term)))
    .map((entry) => ({ entry, score: terms.filter((term) => entry.normalizedTitle.includes(term)).length }))
    .sort((a, b) => b.score - a.score)
    .map(({ entry }) => entry);
}

function runSearch() {
  const terms = getSearchTerms();
  const conceptEntry = state.glossaryById.get(state.conceptId);

  elements.activeFilter.hidden = !conceptEntry;
  elements.activeFilterLabel.textContent = conceptEntry ? `Concepto: ${conceptEntry.term}` : "";

  if (!terms.length && !conceptEntry) {
    elements.tree.hidden = false;
    elements.searchResults.hidden = true;
    elements.searchStatus.textContent = "";
    return;
  }

  const matches = findMatches(terms);
  elements.tree.hidden = true;
  elements.searchResults.hidden = false;
  elements.searchStatus.textContent = matches.length
    ? pluralize(matches.length, "ejercicio encontrado", "ejercicios encontrados")
    : "Sin resultados. Prueba con otra palabra o quita el filtro de concepto.";
  elements.searchResults.replaceChildren(
    ...matches.slice(0, MAX_SEARCH_RESULTS).map((entry) => renderSearchResult(entry, terms)),
  );
}

function renderSearchResult(entry, terms) {
  const { file, exercise } = entry;
  const link = createElement("a", { attrs: { href: buildHash(file, exercise.index) } }, [
    createElement("span", { className: "result-title", html: markTerms(exercise.title, terms) }),
    createElement("span", { className: "result-location", text: `${describeFile(file)}, ${file.title}` }),
  ]);
  const snippet = buildSnippet(entry.snippetSource, terms);
  if (snippet) link.append(createElement("span", { className: "result-snippet", html: snippet }));
  return createElement("li", {}, [link]);
}

/** Normalizes char by char so positions map back to the original text. */
function buildNormalizedMap(text) {
  let normalized = "";
  const originalIndexes = [];
  [...text].forEach((character, index) => {
    const normalizedCharacter = normalizeText(character);
    for (let i = 0; i < normalizedCharacter.length; i += 1) originalIndexes.push(index);
    normalized += normalizedCharacter;
  });
  return { normalized, originalIndexes, characters: [...text] };
}

function findTermRanges(map, terms) {
  const ranges = [];
  for (const term of terms) {
    let from = map.normalized.indexOf(term);
    while (from !== -1) {
      const start = map.originalIndexes[from];
      const end = map.originalIndexes[from + term.length - 1] + 1;
      ranges.push([start, end]);
      from = map.normalized.indexOf(term, from + term.length);
    }
  }
  return ranges.sort((a, b) => a[0] - b[0]);
}

function markTerms(text, terms, map = buildNormalizedMap(text), from = 0, to = map.characters.length) {
  const ranges = findTermRanges(map, terms).filter(([start, end]) => start >= from && end <= to);
  let html = "";
  let cursor = from;
  for (const [start, end] of ranges) {
    if (start < cursor) continue;
    html += escapeHtml(map.characters.slice(cursor, start).join(""));
    html += `<mark>${escapeHtml(map.characters.slice(start, end).join(""))}</mark>`;
    cursor = end;
  }
  return html + escapeHtml(map.characters.slice(cursor, to).join(""));
}

function buildSnippet(text, terms) {
  if (!terms.length || !text) return "";
  const map = buildNormalizedMap(text);
  const firstRange = findTermRanges(map, terms)[0];
  if (!firstRange) return "";
  const from = Math.max(0, firstRange[0] - SNIPPET_RADIUS);
  const to = Math.min(map.characters.length, firstRange[1] + SNIPPET_RADIUS);
  const prefix = from > 0 ? "…" : "";
  const suffix = to < map.characters.length ? "…" : "";
  return prefix + markTerms(text, terms, map, from, to) + suffix;
}

function clearSearch() {
  elements.searchInput.value = "";
  state.query = "";
  runSearch();
}

/* -------------------------------------------------------------------------- */
/* Theme, menu and chrome                                                     */
/* -------------------------------------------------------------------------- */

function readStoredTheme() {
  try {
    return localStorage.getItem(THEME_STORAGE_KEY);
  } catch {
    return null;
  }
}

function storeTheme(theme) {
  try {
    localStorage.setItem(THEME_STORAGE_KEY, theme);
  } catch {
    /* Storage can be unavailable (private mode); the theme still applies. */
  }
}

function getEffectiveTheme() {
  const explicitTheme = document.documentElement.dataset.theme;
  if (explicitTheme) return explicitTheme;
  return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

function updateThemeButton() {
  const nextTheme = getEffectiveTheme() === "dark" ? "claro" : "oscuro";
  elements.themeToggle.setAttribute("aria-label", `Cambiar a tema ${nextTheme}`);
  elements.themeToggle.title = `Cambiar a tema ${nextTheme}`;
}

function initTheme() {
  const storedTheme = readStoredTheme();
  if (storedTheme === "light" || storedTheme === "dark") document.documentElement.dataset.theme = storedTheme;
  updateThemeButton();
  elements.themeToggle.addEventListener("click", () => {
    const nextTheme = getEffectiveTheme() === "dark" ? "light" : "dark";
    document.documentElement.dataset.theme = nextTheme;
    storeTheme(nextTheme);
    updateThemeButton();
  });
}

function isMenuOpen() {
  return elements.layout.classList.contains("is-menu-open");
}

function openMenu() {
  elements.layout.classList.add("is-menu-open");
  document.body.classList.add("is-scroll-locked");
  elements.menuToggle.setAttribute("aria-expanded", "true");
  if (window.matchMedia(MOBILE_QUERY).matches) elements.menuClose.focus({ preventScroll: true });
}

function closeMenu({ restoreFocus = false } = {}) {
  const wasOpen = isMenuOpen();
  elements.layout.classList.remove("is-menu-open");
  document.body.classList.remove("is-scroll-locked");
  elements.menuToggle.setAttribute("aria-expanded", "false");
  if (wasOpen && restoreFocus) elements.menuToggle.focus();
}

function updateMobileTitle() {
  const file = state.fileByKey.get(state.currentFileKey);
  elements.mobileTitle.textContent = file ? `${describeFile(file)}: ${file.title}` : "Apuntes BootDev";
}

function renderIndexInfo() {
  elements.indexInfo.textContent = `Índice generado el ${formatDate(state.index.generatedAt)}`;
}

function showLoadError(error) {
  const isFileProtocol = window.location.protocol === "file:";
  const notice = isFileProtocol
    ? renderNotice(
        "Abre el visor desde un servidor local",
        "El navegador no deja leer el índice al abrir el fichero directamente. Desde la raíz del repositorio ejecuta:",
        "python -m http.server 8000\n# y abre http://localhost:8000/viewer/",
      )
    : renderNotice(
        "No se encontró el índice de apuntes",
        `No se pudo cargar ${INDEX_URL} (${error.message}). Genéralo desde la raíz del repositorio y recarga la página:`,
        "python viewer/build_index.py",
      );
  elements.view.replaceChildren(notice);
  elements.view.hidden = false;
  elements.bootMessage.hidden = true;
}

/* -------------------------------------------------------------------------- */
/* Events and start-up                                                        */
/* -------------------------------------------------------------------------- */

function collectElements() {
  const ids = {
    layout: "layout",
    main: "main-content",
    view: "view",
    bootMessage: "boot-message",
    tree: "course-tree",
    searchInput: "search-input",
    searchResults: "search-results",
    searchStatus: "search-status",
    activeFilter: "active-filter",
    activeFilterLabel: "active-filter-label",
    clearFilter: "clear-filter",
    conceptsHint: "concepts-hint",
    chapterConcepts: "chapter-concepts",
    glossary: "glossary",
    themeToggle: "theme-toggle",
    menuToggle: "menu-toggle",
    menuClose: "menu-close",
    sidebarBackdrop: "sidebar-backdrop",
    mobileTitle: "mobile-title",
    indexInfo: "index-info",
    toast: "toast",
  };
  for (const [name, id] of Object.entries(ids)) elements[name] = document.getElementById(id);
}

function isTypingTarget(target) {
  return target instanceof HTMLElement && (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName));
}

function bindEvents() {
  window.addEventListener("hashchange", () => handleRoute());

  const debouncedSearch = debounce(() => {
    state.query = elements.searchInput.value;
    runSearch();
  }, SEARCH_DEBOUNCE_MS);
  elements.searchInput.addEventListener("input", debouncedSearch);
  elements.searchInput.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    if (elements.searchInput.value) clearSearch();
    else toggleConceptFilter(null);
  });

  elements.clearFilter.addEventListener("click", () => toggleConceptFilter(state.conceptId));

  document.addEventListener("click", (event) => {
    const conceptButton = event.target.closest("[data-concept-id]");
    if (conceptButton) toggleConceptFilter(conceptButton.dataset.conceptId);
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "/" && !isTypingTarget(event.target)) {
      event.preventDefault();
      if (window.matchMedia(MOBILE_QUERY).matches) openMenu();
      elements.searchInput.focus();
    } else if (event.key === "Escape" && isMenuOpen()) {
      closeMenu({ restoreFocus: true });
    }
  });

  elements.menuToggle.addEventListener("click", () => {
    if (isMenuOpen()) closeMenu();
    else openMenu();
  });
  elements.menuClose.addEventListener("click", () => closeMenu({ restoreFocus: true }));
  elements.sidebarBackdrop.addEventListener("click", () => closeMenu({ restoreFocus: true }));
  window.matchMedia(MOBILE_QUERY).addEventListener("change", (event) => {
    if (!event.matches) closeMenu();
  });

  window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", updateThemeButton);
}

async function init() {
  collectElements();
  initTheme();
  bindEvents();

  try {
    prepareIndex(await loadIndex());
  } catch (error) {
    showLoadError(error);
    return;
  }

  if (state.index.schemaVersion !== SUPPORTED_SCHEMA_VERSION) {
    showToast("El índice tiene un formato distinto al esperado. Vuelve a generarlo con build_index.py.");
  }

  elements.bootMessage.hidden = true;
  elements.view.hidden = false;
  renderGlossary();
  renderIndexInfo();
  handleRoute({ isInitial: true });
}

init();
